//! `Q32_32`: the wide signed fixed-point intermediate of plane A (SPR-016; `05.1` §6 item 4, v1.10).
//!
//! An `i64` whose value is `bits / 2^32` (32 integer bits, 32 fraction bits): the type between a
//! spec's `Q16_16` parameters and a `Prob32`, and the type of `exp`, `ln_ratio` and
//! `prob_from_hazard` (`translog.rs`). It is generated by the macros of `Q8_8` and `Q16_16`, so it
//! follows every `rh_core::fixed` rule: saturating `add`/`sub`/`mul`, one rounding (half to even),
//! the guarded `checked_div`, no conversion from or to a float under any feature, and no implicit
//! mixing with another fixed-point type (the compile-fail controls `mix-q32-q16`, `q32-float-cast`,
//! `q32-float-from` and `q32-into-prob` in `tests/lint_fixtures/compile_fail/fixed_point/`).
//!
//! The named conversions, after `Q8_8::widen` and `Q16_16::narrow_saturating`: [`Q16_16::widen`]
//! is exact (`bits << 16`); [`Q32_32::narrow_saturating`] rounds half to even to 16 fraction bits,
//! then saturates; [`Prob32::from_q32`] is exact on `[0, 1]` and refuses anything else.
//!
//! REF: `CODEX/05_PROJECT/SPR-016_MortalityF1.md` T-01; `05.1` §6 item 4; SPR-010.

use core::ops::{Add, Mul, Neg, Sub};

use super::arith::fixed_point_arithmetic;
use super::prob::Prob32;
use super::q::{Q16_16, fixed_point_type};
use super::round::{div_round_half_even, saturate_i32, saturate_i64, shr_round_half_even};

fixed_point_type! {
    /// A signed Q32.32 fixed-point number: `i64` bits, value `bits / 2^32`, range
    /// `[-2^31, 2^31 - 2^-32]`. The wide intermediate of the transcendentals (`05.1` §6 item 4).
    ///
    /// There is deliberately no `Div` operator (use `checked_div`) and no conversion from or to a
    /// float (`05.1` §6 item 4).
    Q32_32, storage = i64, int = i32, frac_bits = 32, saturate = saturate_i64
}

fixed_point_arithmetic!(Q32_32, frac_bits = 32, saturate = saturate_i64);

impl Q16_16 {
    /// Converts to `Q32_32` exactly (`bits << 16`): every `Q16_16` value is a `Q32_32` value.
    #[must_use]
    pub const fn widen(self) -> Q32_32 {
        Q32_32::from_bits((self.to_bits() as i64) << 16)
    }
}

impl Q32_32 {
    /// Converts to `Q16_16`, rounding half to even to 16 fractional bits, then saturating.
    #[must_use]
    pub const fn narrow_saturating(self) -> Q16_16 {
        Q16_16::from_bits(saturate_i32(shr_round_half_even(
            self.to_bits() as i128,
            16,
        )))
    }
}

impl Prob32 {
    /// Converts a `Q32_32` probability exactly (the same 32 fraction bits); `None` outside `[0, 1]`.
    #[must_use]
    pub const fn from_q32(p: Q32_32) -> Option<Self> {
        let bits = p.to_bits();
        if bits < 0 {
            None
        } else {
            Self::from_bits(bits.cast_unsigned())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{Prob32, Q16_16, Q32_32};

    #[test]
    fn constants_have_the_documented_bits() {
        assert_eq!(Q32_32::ONE.to_bits(), 1 << 32);
        assert_eq!(Q32_32::FRAC_BITS, 32);
        assert_eq!(Q32_32::from_int(i32::MIN), Q32_32::MIN);
        assert_eq!(Q32_32::from_int(-3).to_bits(), -3 << 32);
        assert_eq!(Q32_32::default(), Q32_32::ZERO);
    }

    #[test]
    fn arithmetic_saturates_and_rounds_half_to_even_once() {
        assert_eq!(Q32_32::MAX + Q32_32::EPSILON, Q32_32::MAX);
        assert_eq!(Q32_32::MIN - Q32_32::EPSILON, Q32_32::MIN);
        assert_eq!(-Q32_32::MIN, Q32_32::MAX);
        assert_eq!(
            Q32_32::from_int(1 << 20) * Q32_32::from_int(1 << 20),
            Q32_32::MAX
        );
        let half = Q32_32::from_bits(1 << 31);
        assert_eq!(Q32_32::EPSILON * half, Q32_32::ZERO); // 0.5 step -> 0
        assert_eq!(Q32_32::from_bits(3) * half, Q32_32::from_bits(2)); // 1.5 steps -> 2
        assert_eq!(Q32_32::from_bits(-3) * half, Q32_32::from_bits(-2));
        assert_eq!(Q32_32::ONE.checked_div(Q32_32::ZERO), None);
        assert_eq!(Q32_32::MIN.checked_div(-Q32_32::ONE), Some(Q32_32::MAX));
        assert_eq!(
            Q32_32::from_ratio(1, 3),
            Some(Q32_32::from_bits(1_431_655_765))
        );
        assert_eq!(Q32_32::from_ratio(1 << 31, 1), None);
    }

    #[test]
    fn widen_is_exact_and_narrow_rounds_half_to_even_then_saturates() {
        for bits in [i32::MIN, -65_537, -1, 0, 1, 65_536, i32::MAX] {
            let q = Q16_16::from_bits(bits);
            assert_eq!(q.widen().to_bits(), i64::from(bits) << 16);
            assert_eq!(q.widen().narrow_saturating(), q);
        }
        assert_eq!(Q32_32::from_bits(1 << 15).narrow_saturating(), Q16_16::ZERO); // half: even
        assert_eq!(
            Q32_32::from_bits(3 << 15).narrow_saturating(),
            Q16_16::from_bits(2)
        );
        assert_eq!(
            Q32_32::from_bits(-(3 << 15)).narrow_saturating(),
            Q16_16::from_bits(-2)
        );
        assert_eq!(Q32_32::from_int(40_000).narrow_saturating(), Q16_16::MAX);
        assert_eq!(Q32_32::from_int(-40_000).narrow_saturating(), Q16_16::MIN);
    }

    #[test]
    fn prob32_from_q32_is_exact_on_zero_to_one_and_refuses_the_rest() {
        assert_eq!(Prob32::from_q32(Q32_32::ONE), Some(Prob32::ONE));
        assert_eq!(Prob32::from_q32(Q32_32::ZERO), Some(Prob32::ZERO));
        assert_eq!(Prob32::from_q32(Q32_32::EPSILON), Some(Prob32::EPSILON));
        assert_eq!(Prob32::from_q32(-Q32_32::EPSILON), None);
        assert_eq!(Prob32::from_q32(Q32_32::ONE + Q32_32::EPSILON), None);
        assert_eq!(Prob32::from_q32(Q32_32::MIN), None);
    }
}
